// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address caller, address target, bool status) public {
        vm.assume(caller != address(0));
        vm.assume(target != caller);
        // owner is the zero address (never initialized), only it can set loggers
        vm.prank(address(0));
        c.setApprovedLogger(target, status);
        // caller's own approval is the opposite of target's status
        vm.prank(address(0));
        c.setApprovedLogger(caller, !status);
        // rule: the queried value must reflect target's status, independent of caller
        assertTrue(c.approvedToLog(target) == status);
    }
}
